import NoticeCard from "../components/NoticeCard";
import { useAccessibility } from "../context/AccessibilityContext";

const notices = [
  { id: 1, title: "Exam Schedule Released", content: "Check the exam dates on the student portal." },
  { id: 2, title: "Holiday Notice", content: "College will remain closed on Monday for a public holiday." },
  { id: 3, title: "Fee Payment Reminder", content: "Last date for fee payment is the 5th of next month." }
];

function Notices() {
  const { profile } = useAccessibility();

  // Decide styles based on the selected profile
  let styles = {
    fontSize: "16px",
    letterSpacing: "normal",
    lineHeight: "normal",
    fontFamily: "inherit"
  };

  if (profile === "lowVision") {
    styles.fontSize = "22px";
  }

  if (profile === "dyslexia") {
    styles.letterSpacing = "1.5px";
    styles.lineHeight = "1.8";
    styles.fontFamily = "Arial, sans-serif";
  }

  return (
    <div style={{ padding: "20px", ...styles }}>
      <h1>Notices</h1>
      {notices.map((notice) => (
        <NoticeCard key={notice.id} title={notice.title} content={notice.content} />
      ))}
    </div>
  );
}

export default Notices;
